MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  FILE
    *file;

  MagickBooleanType
    status;

  register IndexPacket
    *p;

  register PixelIndex
    *colormap;

  size_t
    colormap_size;

  size_t
    scene;

  StatusHandler
    *previous_handler;

  previous_handler = SetStatusHandler(UndefinedStatusHandler);
  scene = 0;
  status = MagickTrue;

  if ((file = fopen(image_info->filename, "wb")) == (FILE *) NULL)
  {
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      FileOpenError, "UnableToOpenFile", "%s", image_info->filename);
    return (MagickBooleanType) MagickFalse;
  }

  if (image->colors > 256)
  {
    colormap_size = 256;
    (void) SetImageColorspace(image, sRGBColorspace);
  }
  else
    colormap_size = image->colors;

  colormap = (PixelIndex *) AcquireQuantumMemory(colormap_size, sizeof(*colormap));
  if (colormap == (PixelIndex *) NULL)
  {
    (void) fclose(file);
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      ResourceLimitError, "MemoryAllocationFailed", "Unable to allocate colormap");
    return (MagickBooleanType) MagickFalse;
  }

  p = image->indexes;
  for (size_t i = 0; i < colormap_size; i++)
  {
    colormap[i] = *p;
    p++;
  }

  if (fwrite(colormap, sizeof(*colormap), colormap_size, file) != colormap_size)
  {
    (void) fclose(file);
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      FileWriteError, "UnableToWriteFile", "%s", image_info->filename);
    status = MagickFalse;
  }

  p = image->indexes;
  for (size_t y = 0; y < image->rows; y++)
  {
    if (fwrite(p, sizeof(*p), image->columns, file) != image->columns)
    {
      (void) fclose(file);
      (void) ThrowMagickException(&image->exception, GetMagickModule(),
        FileWriteError, "UnableToWriteFile", "%s", image_info->filename);
      status = MagickFalse;
      break;
    }
    p += image->columns;
  }

  (void) fclose(file);
  colormap = (PixelIndex *) RelinquishMagickMemory(colormap);
  (void) SetStatusHandler(previous_handler);
  return status;
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  FILE
    *file;

  MagickBooleanType
    status;

  MapInfo
    *map_info;

  register IndexPacket
    *p;

  register PixelIndex
    *indexes;

  size_t
    image_size;

  StringInfo
    *colormap;

  /* Open output file for writing */
  file = fopen(image_info->filename, "wb");
  if (file == (FILE *) NULL)
  {
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      FileOpenError, "Unable to open file", "%s", image_info->filename);
    return(MagickFalse);
  }

  /* Transform colorspace to sRGB if necessary */
  if (image->colorspace != sRGBColorspace)
  {
    (void) TransformImageColorspace(image, sRGBColorspace, &image->exception);
  }

  /* Allocate memory for colormap and pixel data */
  image_size = image->columns * image->rows;
  colormap = AcquireStringInfo(256 * sizeof(PixelIndex));
  if (colormap == (StringInfo *) NULL)
  {
    (void) fclose(file);
    return(MagickFalse);
  }

  /* Generate and write colormap */
  map_info = (MapInfo *) NULL;
  map_info = (MapInfo *) AcquireMemory(sizeof(*map_info));
  if (map_info == (MapInfo *) NULL)
  {
    (void) fclose(file);
    RelinquishMagickMemory(colormap);
    return(MagickFalse);
  }

  map_info->red = (unsigned char *) AcquireQuantumMemory(256, sizeof(*map_info->red));
  map_info->green = (unsigned char *) AcquireQuantumMemory(256, sizeof(*map_info->green));
  map_info->blue = (unsigned char *) AcquireQuantumMemory(256, sizeof(*map_info->blue));

  if (map_info->red == (unsigned char *) NULL || map_info->green == (unsigned char *) NULL ||
      map_info->blue == (unsigned char *) NULL)
  {
    (void) fclose(file);
    RelinquishMagickMemory(colormap);
    RelinquishMagickMemory(map_info);
    return(MagickFalse);
  }

  for (size_t i = 0; i < 256; i++)
  {
    map_info->red[i] = ClampToQuantum(QuantumRange * (double) i / 255.0);
    map_info->green[i] = ClampToQuantum(QuantumRange * (double) i / 255.0);
    map_info->blue[i] = ClampToQuantum(QuantumRange * (double) i / 255.0);
  }

  size_t colormap_size = 256 * 3;
  for (size_t i = 0; i < colormap_size; i++)
  {
    unsigned char data = 0;
    if (i % 3 == 0)
      data = map_info->red[i / 3];
    else if (i % 3 == 1)
      data = map_info->green[i / 3];
    else
      data = map_info->blue[i / 3];
    (void) fputc(data, file);
  }

  /* Write pixel indexes */
  indexes = (PixelIndex *) AcquireQuantumMemory(image_size, sizeof(*indexes));
  if (indexes == (PixelIndex *) NULL)
  {
    (void) fclose(file);
    RelinquishMagickMemory(colormap);
    RelinquishMagickMemory(map_info);
    return(MagickFalse);
  }

  p = indexes;
  for (register ssize_t y = 0; y < (ssize_t) image->rows; y++)
  {
    register PixelPacket *q = GetVirtualPixels(image, 0, y, image->columns, 1, &image->exception);
    for (register ssize_t x = 0; x < (ssize_t) image->columns; x++)
    {
      size_t index = (size_t) (QuantumScale * q->red * 255.0 + 0.5);
      *p++ = (PixelIndex) index;
      q++;
    }
  }

  for (register size_t i = 0; i < image_size; i++)
    (void) fputc((unsigned char) indexes[i], file);

  /* Memory cleanup */
  fclose(file);
  RelinquishMagickMemory(indexes);
  RelinquishMagickMemory(map_info);
  RelinquishMagickMemory(colormap);

  return(MagickTrue);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image) {
  ExceptionInfo
    *exception;

  FILE
    *file;

  MagickBooleanType
    status;

  register ssize_t
    i;

  size_t
    number_colors;

  register PixelPacket
    *p;

  MagickPixelPacket
    *colormap;

  if ((image->columns == 0) || (image->rows == 0))
    return(MagickFalse);

  if (image_info == (const ImageInfo *) NULL)
    return(MagickFalse);

  if (image == (Image *) NULL)
    return(MagickFalse);

  exception = &image->exception;

  file = fopen(image_info->filename, "wb");
  if (file == (FILE *) NULL) {
    ThrowFileException(exception, FileOpenError, CannotOpenFile,
      image_info->filename);
    return(MagickFalse);
  }

  if (image->colorspace != sRGBColorspace)
    (void) SetImageColorspace(image, sRGBColorspace, exception);

  number_colors = (size_t) GetImageColors(image, exception);
  if (number_colors > 256) {
    colormap = (MagickPixelPacket *) AcquireQuantumMemory((size_t) number_colors,
      sizeof(*colormap));
    if (colormap == (MagickPixelPacket *) NULL) {
      fclose(file);
      ThrowBinaryException(ResourceLimitError, UnableToAllocateMemory,
        image_info->filename);
      return(MagickFalse);
    }
    p = SetImagePixels(image, 0, 0, image->columns, image->rows);
    if (p == (PixelPacket *) NULL) {
      colormap = (MagickPixelPacket *) RelinquishMagickMemory(colormap);
      fclose(file);
      return(MagickFalse);
    }
    for (i=0; i < (ssize_t) number_colors; i++) {
      colormap[i].red = ClampToQuantum(image->colormap[i].red);
      colormap[i].green = ClampToQuantum(image->colormap[i].green);
      colormap[i].blue = ClampToQuantum(image->colormap[i].blue);
      colormap[i].opacity = ClampToQuantum(image->colormap[i].opacity);
    }
    (void) fwrite(colormap, sizeof(*colormap), number_colors, file);
    colormap = (MagickPixelPacket *) RelinquishMagickMemory(colormap);
  }

  {
    register ssize_t
      x;

    unsigned char
      *indexes = (unsigned char *) AcquireQuantumMemory(image->columns * image->rows, sizeof(*indexes));

    if (indexes == (unsigned char *) NULL) {
      fclose(file);
      ThrowBinaryException(ResourceLimitError, UnableToAllocateMemory,
        image_info->filename);
      return(MagickFalse);
    }

    p = SetImagePixels(image, 0, 0, image->columns, image->rows);
    if (p == (PixelPacket *) NULL) {
      indexes = (unsigned char *) RelinquishMagickMemory(indexes);
      fclose(file);
      return(MagickFalse);
    }

    for (i=0; i < (ssize_t) image->rows; i++) {
      for (x=0; x < (ssize_t) image->columns; x++) {
        indexes[i * image->columns + x] = (unsigned char) GetPixelIndex(p);
        p++;
      }
      SyncCacheViewPixel(image);
    }

    (void) fwrite(indexes, sizeof(*indexes), image->columns * image->rows, file);
    indexes = (unsigned char *) RelinquishMagickMemory(indexes);
  }

  (void) fclose(file);
  return(MagickTrue);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  int
    count;

  MagickBooleanType
    status;

  register ssize_t
    i;

  register PixelIndex
    *indexes;

  size_t
    colormap_size;

  FILE
    *file;

  if ((image->columns == 0) || (image->rows == 0))
    return(MagickFalse);

  if (image_info == (ImageInfo *) NULL)
    return(MagickFalse);

  if (image == (Image *) NULL)
    return(MagickFalse);

  if (image->storage_class != PseudoClass)
    (void) TransformImageColorspace(image, sRGBColorspace);

  if (image->colors > 256)
    {
      (void) TransformImageColorspace(image, sRGBColorspace);
      colormap_size = image->colors * sizeof(PixelPacket);
    }
  else
    colormap_size = 256 * sizeof(PixelPacket);

  if (AllocateImageColormap(image, (size_t) 256) == MagickFalse)
    {
      (void) ThrowMagickException(&image->exception, GetMagickModule(),
        ResourceLimitError, "UnableToAllocateColormap",
        "Unable to allocate colormap");
      return(MagickFalse);
    }

  if ((file = fopen(image->filename, "wb")) == (FILE *) NULL)
    {
      (void) ThrowMagickException(&image->exception, GetMagickModule(),
        FileOpenError, "UnableToCreateImageFile", "%s", image->filename);
      return(MagickFalse);
    }

  if (image->colors > 256)
    count = (int) image->colors;
  else
    count = 256;

  status = WriteImageColormap(image, file, count);

  if (status != MagickTrue)
    {
      (void) fclose(file);
      return(MagickFalse);
    }

  indexes = (PixelIndex *) AcquireQuantumMemory(image->columns * image->rows,
    sizeof(PixelIndex));

  if (indexes == (PixelIndex *) NULL)
    {
      (void) fclose(file);
      (void) ThrowMagickException(&image->exception, GetMagickModule(),
        ResourceLimitError, "UnableToAllocateMemory",
        "Unable to allocate memory for pixel indexes");
      return(MagickFalse);
    }

  for (i = 0; i < (ssize_t) (image->columns * image->rows); i++)
    indexes[i] = (PixelIndex) i;

  (void) fwrite(indexes, sizeof(PixelIndex), image->columns * image->rows, file);

  (void) fclose(file);
  indexes = (PixelIndex *) RelinquishQuantumMemory(indexes);

  return(MagickTrue);
}

MagickBooleanType WriteMAPImage(const ImageInfo *image_info, Image *image)
{
  FILE *file;
  register ssize_t x;
  size_t
    depth,
    number_pixels,
    number_colors;
  ssize_t y;
  MagickBooleanType status;
  Colormap colormap;
  Quantum *pixels;
  MagickOffsetType scene;

  if ((file = fopen(image->filename, "wb")) == (FILE *) NULL)
  {
    (void) ThrowMagickException(&image->exception, GetMagickModule(),
      FileOpenError, "Unable to create file", "%s", image->filename);
    return MagickFalse;
  }

  if (image->colorspace != sRGBColorspace)
    (void) TransformImageColorspace(image, sRGBColorspace, &image->exception);

  depth = 8;
  number_colors = (1UL << depth);
  colormap = (Colormap) AcquireQuantumInfo(image, image->quantum_info);
  if (colormap == (Colormap) NULL)
  {
    (void) fclose(file);
    return MagickFalse;
  }

  if (AcquireImageColormap(image, number_colors, &image->exception) == MagickFalse)
  {
    (void) fclose(file);
    colormap = (Colormap) RelinquishQuantumInfo(colormap);
    return MagickFalse;
  }

  if (WriteBlob(FILE *, size_t, size_t, void *))
  {
    (void) fclose(file);
    colormap = (Colormap) RelinquishQuantumInfo(colormap);
    return MagickFalse;
  }

  for (y = 0; y < (ssize_t) image->rows; y++)
  {
    register PixelTrait *p;
    register unsigned int *indexes;
    register PixelInfo *q;
    Quantum *pixels;
    size_t length;
    ssize_t x;

    pixels = (Quantum *) AcquireQuantumMemory(image->columns, sizeof(*pixels));
    if (pixels == (Quantum *) NULL)
    {
      (void) fclose(file);
      colormap = (Colormap) RelinquishQuantumInfo(colormap);
      return MagickFalse;
    }

    indexes = (unsigned int *) AcquireQuantumMemory(image->columns, sizeof(*indexes));
    if (indexes == (unsigned int *) NULL)
    {
      colormap = (Colormap) RelinquishQuantumInfo(colormap);
      pixels = (Quantum *) RelinquishQuantumMemory(pixels);
      (void) fclose(file);
      return MagickFalse;
    }

    (void) GetPixelInfo(image, &image->exception);
    (void) GetPixelInfo(image, &image->exception);
    (void) GetPixelInfo(image, &image->exception);

    for (x = 0; x < (ssize_t) image->columns; x++)
    {
      p = &pixels[x];
      q = &image->pixels[y * image->columns + x];
      indexes[x] = q->index;
    }

    (void) fwrite(indexes, sizeof(*indexes), image->columns, file);

    pixels = (Quantum *) RelinquishQuantumMemory(pixels);
    indexes = (unsigned int *) RelinquishQuantumMemory(indexes);
  }

  colormap = (Colormap) RelinquishQuantumInfo(colormap);
  (void) fclose(file);
  return MagickTrue;
}
